package com.bumptech.glide.load.engine.bitmap_recycle;

/**
 * Standalone test to verify that GroupedLinkedMap recycles the ENTRY's key (not the caller's key)
 * when put() or get() is called with an existing key.
 *
 * Bug: In put() at line 32 and get() at line 45, the code calls key.offer() where 'key' is the
 * method parameter. The correct behavior is to call entry.key.offer() (the stored entry's key).
 *
 * This test demonstrates the bug by:
 * 1. Creating two equal-but-distinct key objects (key1 and key2)
 * 2. Putting key1 into the map (creates entry with key1 stored)
 * 3. Putting/getting with key2 (entry exists, should recycle key1 not key2)
 * 4. Checking which key's offer() was called
 */
public class GroupedLinkedMapRecycleKeyBugTest {

  private static int failures = 0;
  private static int testsRun = 0;

  public static void main(String[] args) {
    GroupedLinkedMapRecycleKeyBugTest test = new GroupedLinkedMapRecycleKeyBugTest();

    test.testPutRecyclesEntryKeyNotCallerKeyWhenKeyExists();
    test.testGetRecyclesEntryKeyNotCallerKeyWhenKeyExists();
    test.testPutDoesNotRecycleKeyOnFirstInsert();

    System.out.println("Tests run: " + testsRun + ", Failures: " + failures);
    if (failures > 0) {
      System.exit(1);
    }
  }

  private void assertTrue(String msg, boolean condition) {
    testsRun++;
    if (!condition) {
      failures++;
      System.err.println("FAILED: " + msg);
    }
  }

  private void assertFalse(String msg, boolean condition) {
    assertTrue(msg, !condition);
  }

  public void testPutRecyclesEntryKeyNotCallerKeyWhenKeyExists() {
    GroupedLinkedMap<TrackingKey, Object> map = new GroupedLinkedMap<>();
    TrackingKey key1 = new TrackingKey("key", 1, 1);
    TrackingKey key2 = new TrackingKey("key", 1, 1);

    // First put: entry created, key1 stored in entry
    map.put(key1, "value1");
    assertFalse("key1 should not be offered on first put", key1.wasOffered);

    // Second put with an equal but different key object: entry already exists
    // CORRECT: entry.key.offer() should be called (key1.offer())
    // BUGGY: key.offer() is called (key2.offer())
    map.put(key2, "value2");

    // The entry's key (key1) should have been recycled, not the caller's key (key2)
    assertTrue("entry key (key1) should have been recycled on second put", key1.wasOffered);
    assertFalse("caller key (key2) should NOT have been recycled on second put", key2.wasOffered);
  }

  public void testGetRecyclesEntryKeyNotCallerKeyWhenKeyExists() {
    GroupedLinkedMap<TrackingKey, Object> map = new GroupedLinkedMap<>();
    TrackingKey key1 = new TrackingKey("key", 1, 1);
    TrackingKey key2 = new TrackingKey("key", 1, 1);

    // First put: entry created, key1 stored in entry
    map.put(key1, "value1");
    assertFalse("key1 should not be offered on put", key1.wasOffered);

    // Get with an equal but different key object: entry already exists
    // CORRECT: entry.key.offer() should be called (key1.offer())
    // BUGGY: key.offer() is called (key2.offer())
    map.get(key2);

    // The entry's key (key1) should have been recycled, not the caller's key (key2)
    assertTrue("entry key (key1) should have been recycled on second get", key1.wasOffered);
    assertFalse("caller key (key2) should NOT have been recycled on second get", key2.wasOffered);
  }

  public void testPutDoesNotRecycleKeyOnFirstInsert() {
    GroupedLinkedMap<TrackingKey, Object> map = new GroupedLinkedMap<>();
    TrackingKey key = new TrackingKey("key", 1, 1);

    // First put: entry created, key stored in entry — no recycling needed
    map.put(key, "value");

    assertFalse("key should not be recycled when entry is first created", key.wasOffered);
  }

  /**
   * A Poolable key that tracks whether its offer() method was called.
   */
  private static final class TrackingKey implements Poolable {
    boolean wasOffered = false;
    private final String key;
    private final int width;
    private final int height;

    TrackingKey(String key, int width, int height) {
      this.key = key;
      this.width = width;
      this.height = height;
    }

    @Override
    public boolean equals(Object o) {
      if (o instanceof TrackingKey) {
        TrackingKey other = (TrackingKey) o;
        return key.equals(other.key) && width == other.width && height == other.height;
      }
      return false;
    }

    @Override
    public int hashCode() {
      int result = key.hashCode();
      result = 31 * result + width;
      result = 31 * result + height;
      return result;
    }

    @Override
    public void offer() {
      wasOffered = true;
    }
  }
}

