package com.bumptech.glide.load.engine.bitmap_recycle;

import static com.bumptech.glide.RobolectricConstants.ROBOLECTRIC_SDK;
import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertNull;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;

@RunWith(RobolectricTestRunner.class)
@Config(sdk = ROBOLECTRIC_SDK)
public class GroupedLinkedMapTest {

  private GroupedLinkedMap<Key, Object> map;

  @Before
  public void setUp() {
    map = new GroupedLinkedMap<>();
  }

  @Test
  public void testReturnsNullForGetWithNoBitmap() {
    Key key = new Key("key", /* width= */ 1, /* height= */ 1);
    assertNull(map.get(key));
  }

  @Test
  public void testCanAddAndRemoveABitmap() {
    Key key = new Key("key", 1, 1);
    Object expected = new Object();

    map.put(key, expected);

    assertThat(map.get(key)).isEqualTo(expected);
  }

  @Test
  public void testCanAddAndRemoveMoreThanOneBitmapForAGivenKey() {
    Key key = new Key("key", 1, 1);
    Integer value = 20;

    int numToAdd = 10;

    for (int i = 0; i < numToAdd; i++) {
      map.put(key, value);
    }

    for (int i = 0; i < numToAdd; i++) {
      assertThat(map.get(key)).isEqualTo(value);
    }
  }

  @Test
  public void testLeastRecentlyRetrievedKeyIsLeastRecentlyUsed() {
    Key firstKey = new Key("key", 1, 1);
    Integer firstValue = 10;
    map.put(firstKey, firstValue);
    map.put(firstKey, firstValue);

    Key secondKey = new Key("key", 2, 2);
    Integer secondValue = 20;
    map.put(secondKey, secondValue);

    map.get(firstKey);

    assertThat(map.removeLast()).isEqualTo(secondValue);
  }

  @Test
  public void testAddingAnEntryDoesNotMakeItMostRecentlyUsed() {
    Key firstKey = new Key("key", 1, 1);
    Integer firstValue = 10;

    map.put(firstKey, firstValue);
    map.put(firstKey, firstValue);

    map.get(firstKey);

    Integer secondValue = 20;
    map.put(new Key("key", 2, 2), secondValue);

    assertThat(map.removeLast()).isEqualTo(secondValue);
  }

  @Test
  public void testPutRecyclesEntryKeyNotCallerKeyWhenKeyExists() {
    TrackingKey key1 = new TrackingKey("key", 1, 1);
    TrackingKey key2 = new TrackingKey("key", 1, 1);

    // First put: entry created, key1 stored in entry
    map.put(key1, "value1");

    // Second put with an equal but different key object: entry already exists
    // The BUGGY code calls key2.offer() (the caller's key)
    // The CORRECT code should call entry.key.offer() which is key1.offer()
    map.put(key2, "value2");

    // The entry's key (key1) should have been recycled, not the caller's key (key2)
    assertThat(key1.wasOffered).isTrue();
    assertThat(key2.wasOffered).isFalse();
  }

  @Test
  public void testGetRecyclesEntryKeyNotCallerKeyWhenKeyExists() {
    TrackingKey key1 = new TrackingKey("key", 1, 1);
    TrackingKey key2 = new TrackingKey("key", 1, 1);

    // First put: entry created, key1 stored in entry
    map.put(key1, "value1");

    // Get with an equal but different key object: entry already exists
    // The BUGGY code calls key2.offer() (the caller's key)
    // The CORRECT code should call entry.key.offer() which is key1.offer()
    map.get(key2);

    // The entry's key (key1) should have been recycled, not the caller's key (key2)
    assertThat(key1.wasOffered).isTrue();
    assertThat(key2.wasOffered).isFalse();
  }

  private static final class TrackingKey implements Poolable {
    boolean wasOffered = false;
    private final String key;
    private final int width;
    private final int height;

    TrackingKey(String key, int width, int height) {
      this.key = key;
      this.width = width;
      this.height = height;
    }

    @Override
    public boolean equals(Object o) {
      if (o instanceof TrackingKey) {
        TrackingKey other = (TrackingKey) o;
        return key.equals(other.key) && width == other.width && height == other.height;
      }
      return false;
    }

    @Override
    public int hashCode() {
      int result = key.hashCode();
      result = 31 * result + width;
      result = 31 * result + height;
      return result;
    }

    @Override
    public void offer() {
      wasOffered = true;
    }
  }

  private static final class Key implements Poolable {

    private final String key;
    private final int width;
    private final int height;

    Key(String key, int width, int height) {
      this.key = key;
      this.width = width;
      this.height = height;
    }

    @Override
    public boolean equals(Object o) {
      if (o instanceof Key) {
        Key other = (Key) o;
        return key.equals(other.key) && width == other.width && height == other.height;
      }
      return false;
    }

    @Override
    public int hashCode() {
      int result = key != null ? key.hashCode() : 0;
      result = 31 * result + width;
      result = 31 * result + height;
      return result;
    }

    @Override
    public void offer() {
      // Do nothing.
    }
  }
}

