package com.bumptech.glide.load.engine.cache;

import static com.google.common.truth.Truth.assertThat;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.AdditionalMatchers.not;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import com.bumptech.glide.util.LruCache;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/**
 * Standalone test for the size == maxSize bug that doesn't need Mockito or Truth.
 */
@RunWith(JUnit4.class)
public class LruCacheMaxSizeBugTest {

  private static final int MAX_SIZE = 10;

  /**
   * An LruCache where every item has size = MAX_SIZE.
   */
  private static class FixedSizeLruCache extends LruCache<String, Object> {
    private Object evictedItem = null;

    FixedSizeLruCache() {
      super(MAX_SIZE);
    }

    @Override
    protected int getSize(@Nullable Object item) {
      return MAX_SIZE;
    }

    @Override
    protected void onItemEvicted(@NonNull String key, @Nullable Object item) {
      evictedItem = item;
    }

    public Object getEvictedItem() {
      return evictedItem;
    }
  }

  /**
   * Tests that an item whose size exactly equals the max cache size should be
   * accepted into an empty cache. The cache has room for it (currentSize=0, maxSize=10, itemSize=10).
   * The buggy code uses >= instead of > which rejects this valid item.
   */
  @Test
  public void put_itemWithSizeEqualToMaxSizeInEmptyCache_isAccepted() {
    FixedSizeLruCache cache = new FixedSizeLruCache();
    Object item = new Object();
    String key = "key1";

    // Cache is empty, item size == maxSize. Should be accepted.
    cache.put(key, item);

    // The item should be retrievable from the cache
    assertEquals("Item should be in cache after put", item, cache.get(key));
    // The item should NOT have been evicted
    assertNull("Item should NOT have been evicted when size == maxSize in empty cache",
               cache.getEvictedItem());
  }
}

@RunWith(JUnit4.class)
public class LruCacheTest {
  private static final int SIZE = 10;
  private LruCache<String, Object> cache;
  private CacheListener listener;
  private String currentKey;

  @Before
  public void setUp() {
    currentKey = "";
    listener = mock(CacheListener.class);
    cache = new TestLruCache(SIZE, listener);
    when(listener.getSize(any())).thenReturn(1);
  }

  @Test
  public void testCanAddAndRetrieveItem() {
    String key = getKey();
    Object object = new Object();

    cache.put(key, object);

    assertEquals(object, cache.get(key));
  }

  @Test
  public void testCanPutNullItemWithoutChangingSize() {
    String key = getKey();
    cache.put(key, null);

    for (int i = 0; i < SIZE; i++) {
      cache.put(getKey(), new Object());
    }

    verify(listener, never()).onItemRemoved(any());
  }

  @Test
  public void testReplacingNonNullItemWithNullItemDecreasesSize() {
    String key = getKey();
    Object initialValue = new Object();
    cache.put(key, initialValue);
    cache.put(key, null);

    for (int i = 0; i < SIZE; i++) {
      cache.put(getKey(), new Object());
    }

    verify(listener).onItemRemoved(initialValue);
  }

  @Test
  public void testReplacingNullItemWIthNullItemIncreasesSize() {
    String key = getKey();
    cache.put(key, null);
    cache.put(key, new Object());

    for (int i = 0; i < SIZE; i++) {
      cache.put(getKey(), new Object());
    }

    verify(listener).onItemRemoved(any());
  }

  @Test
  public void testReplacingNonNullItemWithNonNullItemUpdatesSize() {
    String key = getKey();
    Object initialValue = new Object();
    cache.put(key, initialValue);
    cache.put(key, new Object());

    for (int i = 0; i < SIZE - 1; i++) {
      cache.put(getKey(), new Object());
    }

    verify(listener).onItemRemoved(initialValue);
    verify(listener, never()).onItemRemoved(not(eq(initialValue)));
  }

  @Test
  public void testCacheContainsAddedBitmap() {
    final String key = getKey();
    cache.put(key, new Object());
    assertTrue(cache.contains(key));
  }

  @Test
  public void testEmptyCacheDoesNotContainKey() {
    assertFalse(cache.contains(getKey()));
  }

  @Test
  public void testItIsSizeLimited() {
    for (int i = 0; i < SIZE; i++) {
      cache.put(getKey(), new Object());
    }
    verify(listener, never()).onItemRemoved(any());
    cache.put(getKey(), new Object());
    verify(listener).onItemRemoved(any());
  }

  @Test
  public void testLeastRecentlyAddKeyEvictedFirstIfGetsAreEqual() {
    Object first = new Object();
    cache.put(getKey(), first);
    for (int i = 0; i < SIZE; i++) {
      cache.put(getKey(), new Object());
    }

    verify(listener).onItemRemoved(eq(first));
    verify(listener, times(1)).onItemRemoved(any(Object.class));
  }

  @Test
  public void testLeastRecentlyUsedKeyEvictedFirst() {
    String mostRecentlyUsedKey = getKey();
