package com.bumptech.glide.util;

/**
 * Test for the bug where LruCache.put() rejects items whose size exactly equals maxSize.
 * 
 * Bug: In LruCache.put() at line 132, the condition `itemSize >= maxSize` rejects items
 * whose size is exactly equal to the max cache size. Even when the cache is empty
 * (currentSize is 0), an item with size == maxSize would be rejected and evicted
 * immediately via onItemEvicted(), even though there's technically room for it.
 * 
 * Correct behavior: An item with size exactly equal to maxSize should be accepted
 * when the cache is empty, since it exactly fills the cache capacity. The check
 * should be `itemSize > maxSize` to allow items that exactly fill the cache.
 * 
 * Run with: java -cp <classpath> com.bumptech.glide.util.LruCacheMaxSizeBugTest
 */
public class LruCacheMaxSizeBugTest {

  private static final int MAX_SIZE = 10;
  private static int testsRun = 0;
  private static int testsPassed = 0;
  private static int testsFailed = 0;

  /**
   * An LruCache where every item has size = MAX_SIZE.
   */
  private static class FixedSizeLruCache extends LruCache<String, Object> {
    private Object evictedItem = null;

    FixedSizeLruCache() {
      super(MAX_SIZE);
    }

    @Override
    protected int getSize(Object item) {
      return MAX_SIZE;
    }

    @Override
    protected void onItemEvicted(String key, Object item) {
      evictedItem = item;
    }

    public Object getEvictedItem() {
      return evictedItem;
    }
  }

  private static void assertEquals(String message, Object expected, Object actual) {
    if (!java.util.Objects.equals(expected, actual)) {
      throw new AssertionError(message + ": expected " + expected + " but was " + actual);
    }
  }

  private static void assertNull(String message, Object actual) {
    if (actual != null) {
      throw new AssertionError(message + ": expected null but was " + actual);
    }
  }

  private static void assertNotNull(String message, Object actual) {
    if (actual == null) {
      throw new AssertionError(message + ": expected non-null but was null");
    }
  }

  /**
   * Tests that an item whose size exactly equals the max cache size should be
   * accepted into an empty cache. The cache has room for it (currentSize=0, maxSize=10, itemSize=10).
   * The buggy code uses >= instead of > which rejects this valid item.
   */
  public static void test_put_itemWithSizeEqualToMaxSizeInEmptyCache_isAccepted() {
    testsRun++;
    try {
      FixedSizeLruCache cache = new FixedSizeLruCache();
      Object item = new Object();
      String key = "key1";

      // Cache is empty, item size == maxSize. Should be accepted.
      cache.put(key, item);

      // The item should be retrievable from the cache
      assertEquals("Item should be in cache after put", item, cache.get(key));
      // The item should NOT have been evicted
      assertNull("Item should NOT have been evicted when size == maxSize in empty cache",
                 cache.getEvictedItem());
      testsPassed++;
      System.out.println("PASS: test_put_itemWithSizeEqualToMaxSizeInEmptyCache_isAccepted");
    } catch (AssertionError e) {
      testsFailed++;
      System.out.println("FAIL: test_put_itemWithSizeEqualToMaxSizeInEmptyCache_isAccepted: " + e.getMessage());
    }
  }

  /**
   * Tests that an item whose size exceeds the max cache size is still rejected.
   */
  public static void test_put_itemWithSizeExceedingMaxSize_isRejected() {
    testsRun++;
    try {
      FixedSizeLruCache cache = new FixedSizeLruCache();

      // Override to make item size > maxSize
      class OverSizedCache extends LruCache<String, Object> {
        private Object evictedItem = null;
        public Object getEvictedItem() { return evictedItem; }

        OverSizedCache() {
          super(MAX_SIZE);
        }

        @Override
        protected int getSize(Object item) {
          return MAX_SIZE + 1;
        }

        @Override
        protected void onItemEvicted(String key, Object item) {
          evictedItem = item;
        }
      }

      OverSizedCache overSized = new OverSizedCache();
      Object item = new Object();
      overSized.put("key1", item);

      // The item should NOT be in the cache
      assertNull("Item should NOT be in cache when size > maxSize", overSized.get("key1"));
      // It should have been evicted
      assertEquals("Item should have been evicted when size > maxSize", item, overSized.getEvictedItem());
      testsPassed++;
      System.out.println("PASS: test_put_itemWithSizeExceedingMaxSize_isRejected");
    } catch (AssertionError e) {
      testsFailed++;
      System.out.println("FAIL: test_put_itemWithSizeExceedingMaxSize_isRejected: " + e.getMessage());
    }
  }

  public static void main(String[] args) {
    System.out.println("Running LruCacheMaxSizeBugTest...");
    System.out.println("===========================================");

    test_put_itemWithSizeEqualToMaxSizeInEmptyCache_isAccepted();
    test_put_itemWithSizeExceedingMaxSize_isRejected();

    System.out.println("===========================================");
    System.out.println("Tests run: " + testsRun + ", passed: " + testsPassed + ", failed: " + testsFailed);

    if (testsFailed > 0) {
      System.exit(1);
    }
  }
}

