package com.bumptech.glide.load.model;

/**
 * Demonstrates the hashCode zero-sentinel bug pattern found in GlideUrl.hashCode().
 * 
 * The bug: using `if (hashCode == 0)` as the lazy-computation guard, where 0 is a
 * valid computed hash code. When the true hash is 0, every call recomputes.
 * 
 * This test replicates the exact pattern from GlideUrl.java lines 141-147:
 *   private int hashCode;
 *   public int hashCode() {
 *       if (hashCode == 0) {
 *           hashCode = getCacheKey().hashCode();
 *           hashCode = 31 * hashCode + headers.hashCode();
 *       }
 *       return hashCode;
 *   }
 * 
 * A correct implementation would use a boolean flag like `boolean hashCodeComputed`
 * instead of relying on the sentinel value 0.
 */
public class HashCodeZeroSentinelTest {

    /**
     * A Headers-like collaborator whose hashCode() call count we can track.
     * In the real code, this is a Headers mock; here we just count invocations.
     */
    static class CountingHeaders {
        private int hash;
        private int callCount = 0;

        CountingHeaders(int hash) {
            this.hash = hash;
        }

        public int hashCode() {
            callCount++;
            return hash;
        }

        public int getCallCount() {
            return callCount;
        }
    }

    /**
     * Reproduces the EXACT buggy pattern from GlideUrl.java hashCode() method.
     * Uses `if (hashCode == 0)` as the uninitialized guard.
     */
    static class BuggyGlideUrlPattern {
        private final String cacheKey;
        private final CountingHeaders headers;
        private int hashCode;

        BuggyGlideUrlPattern(String cacheKey, CountingHeaders headers) {
            this.cacheKey = cacheKey;
            this.headers = headers;
        }

        /** Exact copy of GlideUrl.hashCode() logic */
        public int hashCode() {
            if (hashCode == 0) {
                hashCode = cacheKey.hashCode();
                hashCode = 31 * hashCode + headers.hashCode();
            }
            return hashCode;
        }
    }

    /**
     * The correct pattern: uses a boolean flag to track whether hashCode was computed.
     * This is the fix that should be applied to GlideUrl.java.
     */
    static class FixedGlideUrlPattern {
        private final String cacheKey;
        private final CountingHeaders headers;
        private int hashCode;
        private boolean hashCodeComputed;

        FixedGlideUrlPattern(String cacheKey, CountingHeaders headers) {
            this.cacheKey = cacheKey;
            this.headers = headers;
        }

        public int hashCode() {
            if (!hashCodeComputed) {
                hashCode = cacheKey.hashCode();
                hashCode = 31 * hashCode + headers.hashCode();
                hashCodeComputed = true;
            }
            return hashCode;
        }
    }

    public static void main(String[] args) {
        boolean allPassed = true;

        // Test 1: Buggy pattern recomputes when hash is 0
        String cacheKey = "http://example.com";
        int cacheKeyHash = cacheKey.hashCode();
        int neededHeadersHash = -(31 * cacheKeyHash);

        CountingHeaders headers1 = new CountingHeaders(neededHeadersHash);
        BuggyGlideUrlPattern buggy = new BuggyGlideUrlPattern(cacheKey, headers1);

        int first = buggy.hashCode();
        int second = buggy.hashCode();

        System.out.println("Test 1: Buggy pattern recomputes when hash is 0");
        System.out.println("  Expected hashCode: 0");
        System.out.println("  First call returned: " + first);
        System.out.println("  Second call returned: " + second);
        System.out.println("  headers.hashCode() call count: " + headers1.getCallCount());

        if (first != 0) {
            System.out.println("  FAIL: First hashCode should be 0");
            allPassed = false;
        }
        if (second != 0) {
            System.out.println("  FAIL: Second hashCode should be 0");
            allPassed = false;
        }
        // BUG: headers.hashCode() is called twice because the guard sees 0 and recomputes
        if (headers1.getCallCount() != 1) {
            System.out.println("  BUG CONFIRMED: headers.hashCode() called " + headers1.getCallCount() 
                + " times instead of 1. The `if (hashCode == 0)` guard causes recomputation when true hash is 0.");
            allPassed = false;
        } else {
            System.out.println("  UNEXPECTED: headers.hashCode() called 1 time (bug not reproduced)");
        }

        System.out.println();

        // Test 2: Fixed pattern caches correctly
        CountingHeaders headers2 = new CountingHeaders(neededHeadersHash);
        FixedGlideUrlPattern fixed = new FixedGlideUrlPattern(cacheKey, headers2);

        first = fixed.hashCode();
        second = fixed.hashCode();

        System.out.println("Test 2: Fixed pattern caches correctly when hash is 0");
        System.out.println("  Expected hashCode: 0");
        System.out.println("  First call returned: " + first);
        System.out.println("  Second call returned: " + second);
        System.out.println("  headers.hashCode() call count: " + headers2.getCallCount());

        if (first != 0 || second != 0) {
            System.out.println("  FAIL: hashCode should be 0");
            allPassed = false;
        }
        if (headers2.getCallCount() != 1) {
            System.out.println("  FAIL: headers.hashCode() should be called exactly once");
            allPassed = false;
        } else {
            System.out.println("  PASS: headers.hashCode() called exactly once");
        }

        System.out.println();

        // Test 3: Buggy pattern works fine when hash is non-zero
        CountingHeaders headers3 = new CountingHeaders(42);
        BuggyGlideUrlPattern buggy3 = new BuggyGlideUrlPattern(cacheKey, headers3);

        first = buggy3.hashCode();
        second = buggy3.hashCode();

        System.out.println("Test 3: Buggy pattern works when hash is non-zero");
        System.out.println("  First call returned: " + first);
        System.out.println("  Second call returned: " + second);
        System.out.println("  headers.hashCode() call count: " + headers3.getCallCount());

        if (first != second) {
            System.out.println("  FAIL: hashCode should be consistent");
            allPassed = false;
        }
        if (headers3.getCallCount() != 1) {
            System.out.println("  FAIL: headers.hashCode() should be called once");
            allPassed = false;
        } else {
            System.out.println("  PASS: headers.hashCode() called exactly once");
        }

        System.out.println();
        if (allPassed) {
            System.out.println("All tests passed!");
            System.exit(0);
        } else {
            System.out.println("TESTS FAILED - bug confirmed");
            System.exit(1);
        }
    }
}

