  @Test
  public void hashCodeCachesCorrectlyEvenWhenResultIsZero() {
    // Craft a Headers mock whose hashCode makes the total 31 * cacheKey.hashCode() + headers.hashCode() == 0
    // to prove that the lazy caching still works when the computed hash code is 0.
    String url = "http://example.com";
