    // Call hashCode() twice
    int first = glideUrl.hashCode();
    int second = glideUrl.hashCode();

    // The result should be 0 by construction
    assertEquals(0, first);
    assertEquals(0, second);

    // If caching works correctly, headers.hashCode() should only be called once.
    // The buggy code uses "if (hashCode == 0)" as the uninitialized guard,
    // so when the true hash is 0, it recomputes every time, calling headers.hashCode() again.
