package com.bumptech.glide.util;

/**
 * Test for {@link MultiClassKey}.
 * 
 * These tests verify that toString() includes the third field, since equals() and hashCode()
 * both consider all three fields. This is expected behavior for proper Java object semantics.
 */
public class MultiClassKeyTest {

  private static int failures = 0;
  private static int testsRun = 0;

  public static void main(String[] args) {
    MultiClassKeyTest test = new MultiClassKeyTest();
    try {
      test.toString_shouldIncludeThirdField();
    } catch (AssertionError e) {
      System.err.println("FAILED: toString_shouldIncludeThirdField: " + e.getMessage());
      failures++;
    }
    try {
      test.toString_shouldIncludeThirdField_whenThirdIsNull();
    } catch (AssertionError e) {
      System.err.println("FAILED: toString_shouldIncludeThirdField_whenThirdIsNull: " + e.getMessage());
      failures++;
    }
    try {
      test.toString_shouldDifferentiateKeysWithDifferentThirdField();
    } catch (AssertionError e) {
      System.err.println("FAILED: toString_shouldDifferentiateKeysWithDifferentThirdField: " + e.getMessage());
      failures++;
    }
    try {
      test.toString_shouldBeConsistentWithEquals();
    } catch (AssertionError e) {
      System.err.println("FAILED: toString_shouldBeConsistentWithEquals: " + e.getMessage());
      failures++;
    }
    try {
      test.toString_shouldReflectAllFieldsUsedInHashCode();
    } catch (AssertionError e) {
      System.err.println("FAILED: toString_shouldReflectAllFieldsUsedInHashCode: " + e.getMessage());
      failures++;
    }

    System.out.println("Tests run: " + testsRun + ", Failures: " + failures);
    if (failures > 0) {
      System.exit(1);
    }
  }

  private static void assertTrue(boolean condition, String message) {
    testsRun++;
    if (!condition) {
      throw new AssertionError(message);
    }
  }

  private static void assertFalse(boolean condition, String message) {
    testsRun++;
    if (condition) {
      throw new AssertionError(message);
    }
  }

  private static void assertEquals(Object expected, Object actual, String message) {
    testsRun++;
    if (expected == null ? actual != null : !expected.equals(actual)) {
      throw new AssertionError(message + " expected: " + expected + " but was: " + actual);
    }
  }

  public void toString_shouldIncludeThirdField() {
    MultiClassKey key = new MultiClassKey(String.class, Integer.class, Boolean.class);

    String toString = key.toString();

    // The toString should include the third field for consistency with equals/hashCode
    assertTrue(toString.contains("third"),
        "toString() should contain 'third' field name: " + toString);
    assertTrue(toString.contains("class java.lang.Boolean"),
        "toString() should contain Boolean.class in the third field: " + toString);
  }

  public void toString_shouldIncludeThirdField_whenThirdIsNull() {
    MultiClassKey key = new MultiClassKey(String.class, Integer.class, null);

    String toString = key.toString();

    // The toString should include the third field even when it's null
    assertTrue(toString.contains("third"),
        "toString() should contain 'third' field name: " + toString);
  }

  public void toString_shouldDifferentiateKeysWithDifferentThirdField() {
    MultiClassKey key1 = new MultiClassKey(String.class, Integer.class, Boolean.class);
    MultiClassKey key2 = new MultiClassKey(String.class, Integer.class, Double.class);

    String toString1 = key1.toString();
    String toString2 = key2.toString();

    // Two keys with same first/second but different third should have different toString output
    assertFalse(toString1.equals(toString2),
        "toString() should differ when third field differs: " + toString1 + " vs " + toString2);
  }

  public void toString_shouldBeConsistentWithEquals() {
    MultiClassKey key1 = new MultiClassKey(String.class, Integer.class, Boolean.class);
    MultiClassKey key2 = new MultiClassKey(String.class, Integer.class, Boolean.class);

    // Keys are equal by equals()
    assertEquals(key1, key2, "Keys should be equal");

    // Their toString representations should also be consistent
    assertEquals(key1.toString(), key2.toString(), "Equal keys should have equal toString()");
  }

  public void toString_shouldReflectAllFieldsUsedInHashCode() {
    MultiClassKey key = new MultiClassKey(String.class, Integer.class, Boolean.class);

    String toString = key.toString();

    // toString should contain references to all fields that contribute to hashCode
    // All three fields are used in hashCode, so toString should mention all three
    assertTrue(toString.contains("first"), "toString() should contain 'first': " + toString);
    assertTrue(toString.contains("second"), "toString() should contain 'second': " + toString);
    assertTrue(toString.contains("third"), "toString() should contain 'third': " + toString);
  }
}

